function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // hammer (pragmatism symbol)
  ctx.beginPath();
  ctx.rect(W/2 + 40, H/2 - 20, 20, 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 + 50, H/2 + 20, 10, 20);
  ctx.stroke();

  // gears (representing "what works")
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 60, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2, 20, 0, 2 * Math.PI);
  for (let i = 0; i < 10; i++) {
    ctx.rotate(Math.sin(t + i) * 0.1);
    ctx.lineTo(W/2 - 80 + 20, H/2);
    ctx.stroke();
    ctx.rotate(-Math.sin(t + i) * 0.1);
  }

  ctx.restore();
}
